import{_ as r,a0 as l,w as d,s as m,ao as p,I as o,x as s,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"systemd 與 sysVinit 彩版對照表 | LCTT x X-CMD","titleTemplate":false,"description":"systemd 與 sysVinit 彩版對照表 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"systemd 與 sysVinit 彩版對照表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"systemd 與 sysVinit 彩版對照表 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140910 Colourful systemd vs sysVinit Linux Cheatsheet","title":"systemd 與 sysVinit 彩版對照表","tag":"201409","desc":""},"relativePath":"201409/20140910 Colourful systemd vs sysVinit Linux Cheatsheet.md","filePath":"[post].md"}'),a={name:"201409/20140910 Colourful systemd vs sysVinit Linux Cheatsheet.md"};function u(y,t,f,x,C,g){const e=l("Link");return d(),m("div",null,[t[18]||(t[18]=p('<h1 id="systemd-與-sysvinit-彩版對照表" tabindex="-1">systemd 與 sysVinit 彩版對照表 <a class="header-anchor" href="#systemd-與-sysvinit-彩版對照表" aria-label="Permalink to “systemd 與 sysVinit 彩版對照表”">​</a></h1><p><strong>systemd</strong> 是一種新型init系統「譯者注：每個操作系統都有一個啓動程序，而Linux init是Linux系統操作中不可缺少的程序之一。所謂的init進程，它是一個由內核啓動的用户級進程。內核自行啓動（已經被載入內存，開始運行，並已初始化所有的設備驅動程序和數據結構等）之後，就通過啓動一個用户級程序init的方式，完成引導進程。所以init始終是第一個進程（其進程編號始終為1）」，最早在Fedora中使用「譯者注：真的嗎？不是Arch？」，經過調整適應了其它許多發行版，例如RedHat、Suse和CentOS。</p><p>歷史上，我們大部分人用過傳統的SysV init 初始化腳本，它通常情況下在/etc/rc.d/init.d/文件夾下。這些腳本調用守護進程二進制代碼，在後台fork一個進程。</p><p>儘管shell腳本非常的靈活，但是很難實現像superviseing（監管）進程和並行執行命令這樣的任務。</p><p>通過對systemd的新式守護進程的介紹，我們發現systemd可以在runtime（運行時）更加簡單的監管和控制守護進程，並且簡化了監控的實現方式（implementation）。</p><p><strong>systemctl</strong>命令是systemd團隊一個非常好的首創。</p><p>這個命令能夠顯示更多的詳細錯誤信息和包括啓動錯誤在內的服務運行時錯誤。systemd引入了一個新術語：<strong>cgroups</strong>（控制組），它基本上是可被分層次安排的進程任務組。「譯者注：這裏簡單介紹一下cgroup（control group）稱為Containers，Containers着眼於資源的分配，利用configfs作配置。它有兩個重要概念：第一是subsystem，內核可以給進程提供的服務/資源；第二是container，一個進程組，成員共享同樣的一個或多個子系統分配限制。Containers是分層次的，一個container可以hold多個container。它的可取之處是創建了一個資源分配的框架，其它開發者可以利用這個框架去開發自己的資源分配patch，比如磁盤設備。」</p><p>如果僅僅通過原來的初始化系統，決定哪個進程是做什麼的、屬於哪個用户的變得越來越困難。</p><p>但是通過systemd，當一個進程派生其它進程時，這些子進程會被自動變成父進程控制組的成員，這樣一來就可以避免繼承的混亂。</p><p><img src="http://images.linoxide.com/systemd-vs-sysVinit-cheatsheet.jpg" alt=""></p>',10)),o("p",null,[t[2]||(t[2]=s("有許多新的運行",-1)),i(e,{href:"http://linoxide.com/linux-command/linux-systemd-commands/"},{default:n(()=>[...t[0]||(t[0]=[s("在 rhel / centos 7.0 上的 systemd 命令",-1)])]),_:1}),t[3]||(t[3]=s("可以替代 sysvinit 的對應命令。你也可以下載 ",-1)),i(e,{href:"http://images.linoxide.com/systemd-vs-sysVinit-cheatsheet.pdf"},{default:n(()=>[...t[1]||(t[1]=[s("本文的 PDF 版本",-1)])]),_:1}),t[4]||(t[4]=s("。",-1))]),t[19]||(t[19]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=s("via: ",-1)),i(e,{href:"http://linoxide.com/linux-command/systemd-vs-sysvinit-cheatsheet/"},{default:n(()=>[...t[5]||(t[5]=[s("http://linoxide.com/linux-command/systemd-vs-sysvinit-cheatsheet/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=s("作者：",-1)),i(e,{href:"http://linoxide.com/author/bobbin/"},{default:n(()=>[...t[7]||(t[7]=[s("Bobbin Zachariah",-1)])]),_:1}),t[11]||(t[11]=s(" 譯者：",-1)),i(e,{href:"https://github.com/szrlee"},{default:n(()=>[...t[8]||(t[8]=[s("szrlee",-1)])]),_:1}),t[12]||(t[12]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[s("Linux中國",-1)])]),_:1}),t[17]||(t[17]=s(" 榮譽推出",-1))])])}const h=r(a,[["render",u]]);export{v as __pageData,h as default};
